/**
 * Upstream statuses that mean “busy”, not “gone”: e-rara answers 503 when the
 * harvest asks too many questions at once (`dc.subject=China` did on
 * 2026-10-19 with 35 SRU queries in flight). They are retried with backoff; a
 * 404/410 is a real answer and is thrown immediately. Network errors and
 * timeouts are retried too, because a cold harvest has no cache to fall back on.
 */
const RETRY_STATUS = new Set([429, 500, 502, 503, 504]);
const RETRIES = Math.max(0, Number(getArg('--retries') ?? 3));

async function get(url, { as = 'text', timeout = 25000 } = {}) {
  const file = cacheFile(url, as);
  if (OFFLINE) {
    const cached = await readFile(file, 'utf8');
    return as === 'json' ? JSON.parse(cached) : cached;
  }
  let lastError = null;
  for (let attempt = 0; attempt <= RETRIES; attempt += 1) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeout);
    try {
      const res = await fetch(url, {
        headers: { 'user-agent': UA, accept: as === 'json' ? 'application/json' : '*/*' },
        signal: ctrl.signal,
      });
      if (!res.ok) {
        const error = new Error(`${res.status} ${url}`);
        // A missing record is an answer; a busy server is worth waiting for.
        if (!RETRY_STATUS.has(res.status) || attempt === RETRIES) throw error;
        lastError = error;
      } else {
        const body = as === 'json' ? await res.json() : await res.text();
        await mkdir(CACHE_DIR, { recursive: true });
        await writeFile(file, as === 'json' ? JSON.stringify(body) : body);
        return body;
      }
    } catch (err) {
      if (attempt === RETRIES) throw err;
      lastError = err;
    } finally {
      clearTimeout(timer);
    }
    const wait = Math.min(8000, 500 * 2 ** attempt) + Math.floor(Math.random() * 250);
    console.error(`retry ${attempt + 1}/${RETRIES} in ${wait} ms after ${lastError.message}`);
    await sleep(wait);
  }
  throw lastError;
}

